 'policies',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid),'[]'::jsonb)) ORDER BY c.relname),'[]'::jsonb)
 FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['profiles','appointments','appointment_change_requests','appointment_logs']) INTO current_metadata;
 IF current_metadata<>original THEN RAISE EXCEPTION 'QA: original public table or RLS metadata changed';END IF;
 IF telecus_integration.payment_receipts_version()<>1 THEN RAISE EXCEPTION 'QA: final migration version invalid';END IF;
END $receipt_final_assertions$;
